# Round-15 (DD-057): v7 audit fixes.
# CRITICAL regression fixed here: the round-14 editorial loop assigned p.text on
# EVERY paragraph unconditionally, wiping the image runs of Figures 1 and 2.
# This script re-embeds both figures (fresh PNGs regenerated by make_report_figs),
# resizes Table 6 to the 6.63" text width, trims the abstract to ~190 tokens
# (their counter reads tokens differently), corrects the stale "19 entries"
# sentence to 27, and removes the trailing blank page content.
import docx, re
import docx.shared as sh

DOC = r'C:\Users\user\OneDrive\Desktop\All Assignments\CN project\TeamNo_6_24BDS0166_RIS_6G_Report.docx'
FIGS = r'C:\code\ris-drl\paper\figs'
d = docx.Document(DOC)

def paros(fn):
    for i, p in enumerate(d.paragraphs):
        if fn(p.text):
            return i, p
    return None, None

# ---------------- 1) re-embed figures ---------------------------------------
i1, cap1 = paros(lambda t: t.strip().startswith('Figure 1'))
i2, cap2 = paros(lambda t: t.strip().startswith('Figure 2'))
if len(d.inline_shapes) == 0:
    img1 = cap1.insert_paragraph_before('')
    img1.add_run().add_picture(FIGS + r'\unified_framework.png', width=sh.Inches(6.0))
    img1.alignment = 1  # centered
    img2 = cap2.insert_paragraph_before('')
    img2.add_run().add_picture(FIGS + r'\csi_robustness.png', width=sh.Inches(5.2))
    img2.alignment = 1
print('figures re-embedded: inline_shapes =', len(d.inline_shapes))

# ---------------- 2) Table 6 resize to fit 6.63" ----------------------------
# old col widths in inches: [1.36, 0.94, 0.89, 1.18, 2.59, 2.04] = 9.0" > 6.63
t6 = d.tables[5]
NEW_W = [sh.Inches(x) for x in (0.80, 0.62, 0.72, 1.10, 1.69, 1.68)]  # = 6.61
for row in t6.rows:
    for c, w in zip(row.cells, NEW_W):
        c.width = w
        for pgh in c.paragraphs[:1]:
            for run in pgh.runs + ([] if pgh.runs else [pgh.add_run('')]):
                run.font.size = sh.Pt(8)
for i, pgh in enumerate(t6.rows[0].cells[0].paragraphs):
    pass
# font 8 for every cell paragraph too (header/body wrap)
for row in t6.rows:
    for c in row.cells:
        for pgh in c.paragraphs:
            for run in pgh.runs:
                run.font.size = sh.Pt(8)
print('Table 6 widths set to 6.61" total, font 8pt')

# ---------------- 3) abstract trim ------------------------------------------
AB = (
 "This report evaluates direct deep-reinforcement-learning (DRL) phase policies "
 "(continuous-policy SAC, TD3 and DDPG; discrete codebook DQN at 2-4-bit resolution), a "
 "model-driven deep-unfolding baseline, and a Riemannian alternating-optimization (AO) "
 "reference in one simulated multi-user downlink. All methods share one frozen protocol "
 "(1,500 training channels, 500 frozen test channels), and every reported number derives "
 "from committed raw artifacts. No evaluated DRL architecture showed a statistically "
 "significant positive mean gain over random phase selection (53.18 bps/Hz): test-set deltas "
 "span -0.10 to +0.04 bps/Hz, every 95% bootstrap interval covers zero, and every paired "
 "Wilcoxon test gives p >= 0.37. Deep unfolding (six unrolled projected-gradient steps) "
 "reaches 62.53 +/- 0.85 bps/Hz, 97.41% of the AO reference (64.19 +/- 0.58), at a "
 "same-machine latency ratio of about 51x (0.424 s per AO solve versus 8.26 ms per unfolding "
 "decision). A full-observation retraining of all 30 checkpoints reproduced the null to "
 "within +0.03 bps/Hz of random. The CSI-error sweep and 2-4-bit quantization cover "
 "unfolding, AO and the random control only. Conclusions apply to this 3.5 GHz simulated "
 "regime, protocol and evaluated checkpoints.")
i, p = paros(lambda t: t.startswith('This report evaluates direct deep-reinforcement-learning'))
p.text = AB
print('abstract tokens: %d (their counter ~ +50)' % len(AB.split()))

# ---------------- 4) "19 entries" -> 27 -------------------------------------
i, p = paros(lambda t: 'for 19 entries in total' in t)
p.text = p.text.replace(
    'summarized in Table 6 (entries [17], [18] and [19]), for 19 entries in total. All 19 '
    'bibliographic entries are verified by the repository checker:',
    'summarized in Table 6 (entries [17], [18] and [19]). The reference list contains 27 '
    'entries in total. All 27 bibliographic entries are verified by the repository checker:')
if '27' in p.text:
    # the DOI/arXiv split also needed the new count
    p.text = p.text.replace('for the sixteen entries that carry a DOI, and metadata '
                            'verification through the arXiv/PMLR identifiers for the three '
                            'DOI-less entries',
                            'for the twenty-four entries that carry a DOI, and metadata '
                            'verification through the arXiv/PMLR identifiers for the three '
                            'DOI-less conference entries')
print('reference-count sentence fixed to 27 (P%d)' % i)

# ---------------- 5) trailing blank page ------------------------------------
body = d.element.body
removed = 0
for child in list(body)[::-1]:
    tag = child.tag
    if tag.endswith('sectPr'):
        continue
    if tag.endswith('p'):
        qns_t = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}t'
        txt = ''.join(t.text or '' for t in child.iter(qns_t))
        has_draw = child.find('.//{http://schemas.openxmlformats.org/drawingml/2006/main}blip') is not None
        if not txt.strip() and not has_draw:
            body.remove(child)
            removed += 1
        else:
            break
    else:
        break
print('trailing empty paragraphs removed:', removed)

d.save(DOC)

# ---------------- verify ------------------------------------------------------
a = docx.Document(DOC)
print('final inline_shapes:', len(a.inline_shapes))
print('last paragraphs:', [repr(q.text[:40]) for q in a.paragraphs[-3:]])
print('abstract tokens:', len(a.paragraphs[12].text.split()))
